import { useState } from "react";

const CreateTask = ({ addTask }) => {
  const [name, setName] = useState('');
  const [desc, setDesc] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    const id = Date.now() + Math.floor(Math.random() * 10000); // generate unique id
    const date = new Date();
    const currentDate = `${date.getMonth()}/${date.getDate() + 1}/${date.getFullYear()}`
    const task = { name, desc, id, currentDate }; // ceate task object
    console.log('Created Task:', name, id);
    addTask(task); // pass the new task to the parent component
    setName(''); // clear name and desc 
    setDesc('');
  };

  //BUGS: When task is created it is not displayed

  return (
    <div className="createTask w-full h-auto flex flex-col items-center justify-center p-5">
      <form
        className="taskForm w-full flex flex-col items-center justify-center"
        onSubmit={handleSubmit}
      >
        <input
          className="taskNameInput pt-2 w-full text-white text-center  md:text-center lg:text-center bg-white bg-opacity-0 rounded-lg focus:outline-none focus:bg-none"
          type="text"
          placeholder="What're you up to?"
          value={name}
          onChange={(e) => setName(e.target.value)} // Update name state on input change
          required
        />
        <textarea
          className="taskDescInput pt-2 w-full text-white text-center text-base md:text-center lg:text-center bg-white bg-opacity-0 rounded-lg focus:outline-none focus:bg-none"
          type="text"
          placeholder="Add a note!"
          value={desc}
          onChange={(e) => setDesc(e.target.value)} // Update desc state on input change
        />
        <div className="addTaskDiv flex flex-col items-center justify-center w-full border-t border-white">
          <button className="addTaskBtn w-fit text-white bg-white bg-opacity-20 p-2 text-center sm:text-center md:text-center lg:text-center bg-white bg-opacity-0 rounded-lg focus:outline-none focus:bg-none flex items-center hover:scale-105 transition duration-100 ease-in-out">
            Add Task</button>
        </div>
      </form>
    </div>
  );
}

export default CreateTask;
